void seq_log(const char *fmt, ...)
{
    char b[1024]; va_list ap;
    va_start(ap, fmt); vsnprintf(b, sizeof(b), fmt, ap); va_end(ap);
    seq_log_msg(b);
}

void blit_path_log(const char *path, const char *fmt, ...)
{
    char b[1024]; va_list ap;
    va_start(ap, fmt); vsnprintf(b, sizeof(b), fmt, ap); va_end(ap);
    blit_path_log_msg(path, b);
}

void gpu_debug_log(const char *fmt, ...)
{
    char b[1024]; va_list ap;
    va_start(ap, fmt); vsnprintf(b, sizeof(b), fmt, ap); va_end(ap);
    gpu_debug_log_msg(b);
}

